import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
ls=json.loads((root/'data/lectures.json').read_text())
fs=json.loads((root/'data/findings.json').read_text())[:3]
def source(title,publisher,url,summary):return dict(title=title,publisher=publisher,url=url,summary=summary)
base='https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/'
upper=source('Muscles of the upper limb','UAMS College of Medicine',base+'muscle-tables/muscles-of-the-upper-limb/','See the named muscle entry and its attachment or action.')
muscles=source('Gross anatomy muscle tables','Texas Tech University Health Sciences Center','https://anatomy.ttuhscep.edu/anatomytables/muscles_alpha.html','See the named muscle entry.')
nerves=source('Nerves of the upper limb','UAMS College of Medicine',base+'nerve-tables/nerves-of-the-upper-limb/','See the named nerve and its branches.')
pelvis=source('Bones of the pelvis and perineum','UAMS College of Medicine',base+'bone-tables/bones-of-the-pelvis-and-perineum/','Lists the ilium and sacral foramina.')
lower=source('Bones of the lower limb','UAMS College of Medicine',base+'bone-tables/bones-of-the-lower-limb/','See the femoral head and fovea entries.')
back=source('Muscles of the back','UAMS College of Medicine',base+'muscle-tables/muscles-of-the-back-region/','See the splenius and serratus posterior inferior entries.')
fcr=source('Tendon of flexor carpi radialis in carpal tunnel','Journal of Clinical Orthopaedics and Trauma','https://pmc.ncbi.nlm.nih.gov/articles/PMC8569728/','Describes the usual separate FCR tunnel and an anatomical variant.')
cubital=source('Dissector answers: axilla, shoulder and arm','Texas Tech University Health Sciences Center','https://anatomy.ttuhscep.edu/schemes/axilla_ans.html','Describes tendon, artery, nerve from lateral to medial.')
def add(n,p,title,why,fix,s,priority='High',kind='Factual discrepancy'):
 l=ls[n-1]; original=next(x['text'] for x in l['paragraphs'] if x['index']==p)
 fs.append(dict(id=f'f-{len(fs)+1:02}',lectureId=l['id'],paragraph=p,title=title,type=kind,priority=priority,explanation=why,suggestion=fix,sources=[s],original=original,checkedAt='2026-10-01',origin='Full lecture AI review · faculty confirmation required'))
add(1,124,"Hangman's fracture: neurological risk",'Typical hangman fractures often widen the canal; spinal cord injury is uncommon rather than common. Atypical patterns can cause neurological injury.',"Hangman's fracture is a traumatic fracture of the C2 pars region. Neurological injury is uncommon in typical patterns, but can occur, especially in atypical or unstable injuries.",source('Management of typical and atypical hangman fractures','Global Spine Journal','https://pmc.ncbi.nlm.nih.gov/articles/PMC4836940/','Distinguishes typical canal widening from atypical neurological risk.'))
for p in [154,156]:add(1,p,'Ilium versus ileum','The pelvic bone is the ilium; ileum names part of the small intestine.',next(x['text'] for x in ls[0]['paragraphs'] if x['index']==p).replace('ileum','ilium'),pelvis,'Medium','Terminology')
add(1,160,'Sacral foramina transmit rami','These foramina transmit spinal nerve rami, after roots have united.', 'Four pairs of anterior and posterior sacral foramina transmit ventral and dorsal rami, respectively.',pelvis)
add(2,94,'Serratus posterior inferior attachment','The standard attachment is ribs 9–12; rib 8 should be checked for a stated variant.','Inferior borders of ribs 9–12, near their angles.',back,'Medium')
add(2,113,'Unilateral versus bilateral splenius action','The ipsilateral action belongs to unilateral contraction, not bilateral contraction.','Unilateral contraction produces ipsilateral lateral flexion and rotation of the head and neck.',back)
add(2,198,'Pelvic landmark terminology','The posterior superior iliac spine is on the ilium, not the ileum.','Location of the posterior superior iliac spine (on the ilium).',pelvis,'Medium','Terminology')
add(3,19,'CNS versus PNS myelination','The definition incorrectly generalizes Schwann-cell myelination to all axons.','Myelin is formed by Schwann cells in the PNS and oligodendrocytes in the CNS.',source('12.2 Nervous tissue','OpenStax','https://openstax.org/books/anatomy-and-physiology-2e/pages/12-2-nervous-tissue','Distinguishes CNS and PNS myelinating glia.'))
add(3,96,'Lumbar nerve labels','C1–C8 identifies cervical nerves, not the five lumbar pairs.','5 lumbar pairs (L1–L5).',source('Anatomy of the spinal cord','UTHealth Houston Neuroscience Online','https://nba.uth.tmc.edu/neuroscience/m/s2/chapter03.html','Lists spinal cord segments and nerve pairs.'))
add(3,169,'Epidural space boundaries','External to the cord also includes intradural spaces; the epidural boundary must specify dura.','The spinal epidural space lies between the spinal dura mater and vertebral canal wall; it contains fat, connective tissue and venous plexuses.',source('13.3 Circulation and the CNS','OpenStax','https://openstax.org/books/anatomy-and-physiology-2e/pages/13-3-circulation-and-the-central-nervous-system','Describes the meninges, epidural and subarachnoid spaces.'))
add(3,187,'CSF circulation versus reabsorption','Sulci contain subarachnoid CSF; they are not its venous reabsorption destination.','CSF circulates in the subarachnoid space, including sulci, and is reabsorbed through arachnoid granulations into dural venous sinuses; other clearance pathways also contribute.',source('13.3 Circulation and the CNS','OpenStax','https://openstax.org/books/anatomy-and-physiology-2e/pages/13-3-circulation-and-the-central-nervous-system','Describes arachnoid granulations and venous reabsorption.'))
add(4,26,'Clavicular ossification pattern','The medial/lateral two-thirds split reverses and oversimplifies clavicular development.','The clavicular shaft develops predominantly by intramembranous ossification; cartilaginous end regions undergo endochondral ossification. Its curvature and cross-sectional geometry contribute to fracture vulnerability.',source('Early development and ossification of the human clavicle','Acta Orthopaedica','https://actaorthop.org/actao/article/view/22403','Embryological study of membranous centers and cartilaginous ends.'))
add(4,129,'Missing posterior deltoid origin','The origin omits the scapular spine and thus the posterior fibers.','Origin: lateral third of clavicle, acromion and spine of scapula.',upper,'Medium','Incomplete anatomical description')
add(4,136,'Gravity and initiation of abduction','Gravity does not initiate upward arm abduction in an upright person; it opposes it.','Supraspinatus assists initiation of arm abduction, with deltoid contributing to abduction. In an upright person gravity opposes lifting the arm.',upper,'Medium','Misleading mechanism')
add(5,85,'Scalene interval of plexus roots','The standard interval is between anterior and middle scalene.','The brachial plexus is formed chiefly by ventral rami C5–T1, emerging between anterior and middle scalene muscles.',source('Brachial plexus variations in interscalene interval','Anatomy & Cell Biology','https://pmc.ncbi.nlm.nih.gov/articles/PMC8480370/','Reports the normal interscalene interval and variants.'))
add(5,127,'Subscapular nerve root values','Assigning C5 alone and C6 alone omits the usual shared root contributions.','Upper and lower subscapular nerves usually carry C5–C6 fibers; contributions can vary.',nerves,'Medium')
add(6,130,'Median nerve in cubital fossa','The median nerve lies medial to the artery, rather than occupying its middle position.','The median nerve passes through the medial cubital fossa, medial to the brachial artery.',cubital)
add(7,22,'Distal ulna and the wrist','The ulnar head articulates with the distal radius, while an articular disc separates it from the carpus.','The ulnar head participates in the distal radioulnar joint; the TFCC separates it from the carpal bones.',source('The triangular fibrocartilage complex in the human wrist','Journal of Anatomy','https://pmc.ncbi.nlm.nih.gov/articles/PMC9322592/','Anatomical study of TFCC structures and joint relationships.'))
add(7,38,'Wrist flexors and the carpal tunnel','The rule needs an FCR exception and must distinguish retinacular structures.','FDS, FDP and FPL tendons traverse the carpal tunnel. FCR usually travels in a separate fibro-osseous tunnel, rather than with them.',fcr,'Medium','Incomplete anatomical description')
add(7,92,'FDP action and joint types','FDP does not flex every hand joint, and the wrist is not a hinge joint.','FDP flexes digits 2–5, especially their distal interphalangeal joints, and assists wrist flexion.',upper,'Medium')
add(7,115,'Brachioradialis insertion','The named insertion should be lateral, not anterior.','Brachioradialis inserts on the lateral distal radius near the styloid process.',upper,'Medium')
add(7,136,'Extensor digiti minimi insertion','The extensor expansion belongs to the fifth digit, not the metacarpal bone.','Inserts into the extensor expansion of the fifth digit.',upper,'Medium')
add(7,151,'Extensor indicis origin','This muscle arises from distal ulna, not radius.','Origin: posterior distal ulna and adjacent interosseous membrane.',muscles)
add(7,165,'Extensor pollicis brevis action','Standard EPB insertion/action primarily extends the MCP joint; IP extension is principally EPL. Variants exist.','EPB primarily extends the thumb at its MCP joint; EPL is the principal IP extensor.',muscles,'Medium')
add(7,171,'Brachial artery relative to biceps tendon','The artery is medial to the tendon rather than superficial to it.','The brachial artery lies medial to the biceps tendon and divides into radial and ulnar arteries in the cubital fossa.',cubital)
add(7,256,'PIN palsy versus complete wrist drop','Isolated PIN dysfunction chiefly impairs finger/thumb extension; wrist extension can remain, with radial deviation.','Compression affecting the posterior interosseous nerve may cause finger and thumb extension weakness without cutaneous sensory loss. Wrist extension is often preserved or weakened with radial deviation, rather than complete wrist drop.',source('Posterior interosseous nerve palsies','Journal of Neurosurgery','https://pubmed.ncbi.nlm.nih.gov/2172858/','Clinical series reports weak wrist extension, radial drift and loss of digital extension.'))
add(7,257,'Arm versus forearm compartment','The PIN supplies forearm extensors; arm names the brachium.','Supplies muscles of the posterior compartment of the forearm.',nerves,'Medium','Terminology')
add(8,89,'Ilium versus ileum','The intended pelvic bone is the ilium.','Ilium',pelvis,'Medium','Terminology')
add(8,113,'Fovea capitis terminology','Fovea centralis names a retinal structure; the femoral pit is fovea capitis.','The fovea capitis on the femoral head provides attachment for the ligament of the head of the femur.',lower,'Medium','Terminology')
for p in [114,149]:add(8,p,'Adult femoral head blood supply','This overstates the usual adult contribution of the ligament artery; the main supply travels along the neck.','In adults, the principal femoral head supply comes from retinacular vessels, chiefly branches of the medial circumflex femoral artery. Their disruption can cause avascular necrosis; the ligament artery is not usually the dominant supply.',source('Anatomy of the medial femoral circumflex artery','Journal of Bone and Joint Surgery (British)','https://pubmed.ncbi.nlm.nih.gov/10963165/','Cadaver study identifies the principal supply from the deep MFCA branch.'))
add(8,190,'Psoas minor does not join iliopsoas insertion','The preceding list includes psoas minor, whose insertion differs.','Psoas major and iliacus join the iliopsoas tendon to the lesser trochanter. Psoas minor, when present, inserts near the iliopubic eminence and pectineal region.',source('Psoas minor','Elsevier Anatomy','https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-lower-limb/psoas-minor/21724','Lists pubic/iliopectineal insertion of psoas minor.'))
add(8,218,'Adductor magnus has two origins','This describes the adductor part but omits the hamstring part.','Adductor magnus: adductor part originates from ischiopubic rami; hamstring part from the ischial tuberosity.',muscles,'Medium','Incomplete anatomical description')
add(8,231,'Superior femoral triangle boundary','The superior boundary is the inguinal ligament, not the canal.','Superior boundary: inguinal ligament.',source('Femoral region','StatPearls / NCBI Bookshelf','https://www.ncbi.nlm.nih.gov/books/NBK538501/','Lists femoral triangle boundaries.'))
add(8,248,'Adductor canal terminology','The named passage is the adductor canal.','The saphenous nerve accompanies femoral vessels through the adductor canal, then leaves before the adductor hiatus.',source('Anterior and medial thigh lab','Texas Tech University Health Sciences Center','https://anatomy.ttuhscep.edu/musculoskeletal_system/thigh.html','Identifies the femoral triangle and adductor canal.'),'Medium','Terminology')
add(8,255,'Femoral artery becomes popliteal','The artery does not become a tibial artery at the hiatus.','After passing through the adductor hiatus, the femoral artery continues as the popliteal artery.',source('Popliteal artery','StatPearls / NCBI Bookshelf','https://www.ncbi.nlm.nih.gov/books/NBK537125/','Defines continuation of femoral artery beyond the adductor hiatus.'))
add(8,261,'Circumflex artery contribution','The lateral transverse branch should not be presented as the major femoral head supply.','The medial circumflex femoral artery provides the principal adult femoral head supply. The lateral circumflex transverse branch contributes to regional anastomoses.',source('Anatomy of the medial femoral circumflex artery','Journal of Bone and Joint Surgery (British)','https://pubmed.ncbi.nlm.nih.gov/10963165/','Identifies the principal femoral head supply.'))
add(8,272,'Femoral canal accommodates vein','This switches the vein to the artery.','The femoral canal permits expansion of the femoral vein during increased venous return.',source('Femoral sheath','StatPearls / NCBI Bookshelf','https://www.ncbi.nlm.nih.gov/sites/books/NBK482388/','Explains the femoral canal and venous expansion.'))
add(9,26,'Typical punching fracture','The classic boxer fracture concerns the fifth metacarpal neck, not a special third-metacarpal susceptibility.','Punching a hard object commonly causes a fifth metacarpal neck (boxer) fracture; other metacarpals may also be injured.',source('Hand fractures','American Academy of Orthopaedic Surgeons','https://www.orthoinfo.org/diseases--conditions/hand-fractures/','Identifies the fifth metacarpal neck as the usual boxer fracture.'))
add(9,55,'FCR retinacular relationship','The superficial rule needs an exception for the usual separate FCR tunnel.','FCU is superficial to the flexor retinaculum; FCR usually passes through its own fibro-osseous tunnel, separate from the carpal tunnel.',fcr,'Medium')
add(9,120,'Hypothenar compartment','Opponens digiti minimi belongs to the hypothenar, not thenar, compartment.','Deep portion of the hypothenar eminence.',muscles,'Medium')
add(9,167,'De Quervain versus trigger finger','These are distinct conditions, involving different tendon tunnels.','De Quervain tenosynovitis affects APL and EPB in the first dorsal wrist compartment. Trigger finger involves digital flexor tendons, usually at the A1 pulley.',source('De Quervain tenosynovitis and trigger finger','American Academy of Orthopaedic Surgeons','https://www.orthoinfo.org/diseases--conditions/de-quervains-tendinosis/','Describes the first dorsal wrist tendon tunnel.'))
fs[-1]['sources'].append(source('Trigger finger','American Academy of Orthopaedic Surgeons','https://www.orthoinfo.org/diseases--conditions/trigger-finger/','Describes digital flexor tendon and A1 pulley narrowing.'))
add(9,189,'Primary versus secondary Raynaud','Idiopathic applies to primary disease; Raynaud can also be secondary.','Raynaud phenomenon causes episodic digital vasospasm, often triggered by cold or stress. Primary disease is idiopathic; secondary disease is associated with another condition.',source('Raynaud phenomenon','NIAMS','https://www.niams.nih.gov/health-topics/raynauds-phenomenon','Distinguishes primary and secondary forms.'),'Medium')
add(9,218,'Ulnar lumbrical motor branch','Placed under superficial-branch discussion, this wrongly implies superficial supply.','Lumbricals 3 and 4 receive motor supply from the deep branch of the ulnar nerve.',nerves)
add(9,222,'Superficial radial nerve distribution','The branch passes to the dorsolateral hand, not into the palm superficial to palmar fascia.','The superficial radial nerve passes to the dorsolateral wrist and hand, supplying dorsal cutaneous branches.',nerves)
add(10,138,'Fifth metatarsal avulsion mechanism','Plantarflexion alone misses the usual inversion mechanism.','Inversion injury, often with plantarflexion, may avulse the fifth metatarsal tuberosity through traction from fibularis brevis and lateral plantar fascia.',source('Fifth metatarsal fractures: update on management','EFORT Open Reviews','https://pmc.ncbi.nlm.nih.gov/articles/PMC8788151/','Distinguishes tuberosity avulsion from Jones fractures.'),'Medium','Misleading mechanism')
add(3,88,'Thoracolumbar lateral horn extent','The sympathetic lateral horn extends across thoracic segments, not just lower thoracic levels.','The prominent sympathetic lateral horn is classically described at T1–L2 spinal cord segments; exact boundaries vary among descriptions.',source('Spinal cord morphology','StatPearls / NCBI Bookshelf','https://www.ncbi.nlm.nih.gov/sites/books/NBK545206/','Describes T1–L2 lateral horn extent.'))
add(3,162,'Continuous spinal catheterization is possible','An intrathecal catheter can be used for continuous spinal anesthesia; inability to catheterize is incorrect.','Single-shot spinal anesthesia is common; continuous spinal anesthesia is also possible using an intrathecal catheter in selected settings.',source('Continuous spinal anaesthesia','BJA Education','https://pmc.ncbi.nlm.nih.gov/articles/PMC9463624/','Reviews intrathecal catheter use for continuous spinal anesthesia.'),'Medium')
add(3,164,'Hangover headache mechanism needs evidence','The proposed CSF-loss and dural-sagging explanation is not established here. The cited agency describes multiple contributing mechanisms.','Alcohol hangover is multifactorial; dehydration, inflammation and other effects can contribute. Do not equate ordinary hangover headache with CSF-leak headache without supporting evidence.',source('Hangovers','National Institute on Alcohol Abuse and Alcoholism','https://www.niaaa.nih.gov/publications/brochures-and-fact-sheets/hangovers','Summarizes several contributing mechanisms.'),'Medium','Unsupported mechanism')
add(9,206,'Median neuropathy is not inevitably irreversible','The absolute claim ignores lesion location, severity and recovery after treatment; carpal tunnel symptoms can improve.','Median nerve dysfunction depends on lesion location and severity. Thenar weakness or atrophy may occur; recovery varies, and persistent severe compression can cause permanent damage.',source('Carpal tunnel syndrome','American Academy of Orthopaedic Surgeons','https://www.orthoinfo.org/diseases--conditions/carpal-tunnel-syndrome/','Describes treatment benefits and risk of permanent nerve damage.'))
for f in fs:f['origin']='Full lecture AI review · faculty confirmation required'
(root/'data/findings.json').write_text(json.dumps(fs,indent=2,ensure_ascii=False))
print('TOTAL',len(fs))
for l in ls:print(l['number'],sum(f['lectureId']==l['id'] for f in fs))
